"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["44221"],{63760(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.codigo_ja_existe","status":409,"titulo":"J\xe1 existe modelo de formul\xe1rio com este c\xf3digo"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.codigo_ja_existe","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o de um modelo de formul\xe1rio (`POST /api/configuracao/admin/modelos-formulario`) usou um `codigo` que j\xe1 pertence a outro modelo. A compara\xe7\xe3o considera todos os modelos, ativos ou desativados, e \xe9 feita com o c\xf3digo aparado nas pontas e normalizado; mai\xfasculas e min\xfasculas contam. O modelo nunca \xe9 apagado, s\xf3 desativado, e o c\xf3digo n\xe3o muda depois de criado, por isso o c\xf3digo de um modelo desativado continua ocupado.","A resposta \xe9 a mesma quando a colis\xe3o \xe9 descoberta na confer\xeancia pr\xe9via e quando dois pedidos criam o mesmo c\xf3digo ao mesmo tempo e o banco recusa o segundo. A recusa vem depois das confer\xeancias do corpo: com um corpo inv\xe1lido e um c\xf3digo j\xe1 usado, a resposta \xe9 a recusa do corpo, e s\xf3 com o corpo v\xe1lido vem esta. Nada \xe9 gravado."],"comoResolver":["Use outro c\xf3digo. Para continuar o modelo que j\xe1 usa esse c\xf3digo, localize-o na listagem (`GET /api/configuracao/admin/modelos-formulario`, que aceita o filtro `ativo=false`), edite-o (`PUT /api/configuracao/admin/modelos-formulario/{id}`) e, se estiver desativado, ative-o (`POST /api/configuracao/admin/modelos-formulario/{id}/ativacao`)."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);